using System;
using System.Collections;
using System.Collections.Generic;
using System.Text;
using UnityEditor;
using UnityEngine;

public class TriangleTexture : EditorWindow
{
    public Texture2D Triangle1Texture;
    public Texture2D Triangle2Texture;

   
    [MenuItem("Window/Duong's Map Maker/Trianglecreadfa")]
    public void Write()
    {
        System.IO.File.WriteAllText("D:/texture_hexa1.text", Convert.ToBase64String(Triangle2Texture.EncodeToPNG()));
        System.IO.File.WriteAllText("D:/texture_hexa2.text", Convert.ToBase64String(Triangle1Texture.EncodeToPNG()));
    }

    #region define

    static string Vertical =
        "";

    static string Horizonal =
        "";
    #endregion

    private static Texture2D _triangleTexture2D;

    public static Texture2D TriangleTexture2D
    {
        get
        {
            if (_triangleTexture2D == null)
            {
                _triangleTexture2D = new Texture2D(1, 1);
                _triangleTexture2D.LoadImage(Convert.FromBase64String(Horizonal));
                _triangleTexture2D.Apply();
            }
            return _triangleTexture2D;
        }
    }

    private static Texture2D _triangle_reveresedTexture2D;
    public static Texture2D TriangleReveresedTexture2D
    {
        get
        {
            if (_triangle_reveresedTexture2D == null)
            {
                _triangle_reveresedTexture2D = new Texture2D(1, 1);
                _triangle_reveresedTexture2D.LoadImage(Convert.FromBase64String(Vertical));
                _triangle_reveresedTexture2D.Apply();
            }
            return _triangle_reveresedTexture2D;
        }
    }

}
